def test_single_value():
    assert average([7]) == 7

def test_empty_input():
    with pytest.raises(ValueError):
        average([])

case.reference:
def average(nums):
    if not nums:
        raise ValueError("An average requires at least one value.")
    return sum(nums) / len(nums)

